class Solution {
  public int minCost(int maxTime, int[][] edges, int[] passingFees) {
    int n = passingFees.length, inf = Integer.MAX_VALUE / 2;
    // dp[t][v]: cheapest way to be in city v exactly t minutes after leaving city 0
    int[][] dp = new int[maxTime + 1][n];
    for (int[] row : dp) Arrays.fill(row, inf);
    dp[0][0] = passingFees[0];
    for (int t = 1; t <= maxTime; t++) {
      for (int[] e : edges) {
        int u = e[0], v = e[1], w = e[2];
        if (t < w) continue;
        if (dp[t - w][u] + passingFees[v] < dp[t][v]) dp[t][v] = dp[t - w][u] + passingFees[v];
        if (dp[t - w][v] + passingFees[u] < dp[t][u]) dp[t][u] = dp[t - w][v] + passingFees[u];
      }
    }
    int best = inf;
    for (int t = 0; t <= maxTime; t++) best = Math.min(best, dp[t][n - 1]);
    return best == inf ? -1 : best;
  }
}
